# SPDX-License-Identifier: MIT
# Independent observer for caps migration fixtures (pane 214).
# Sources: capabilities(7), capget(2)/capset(2), prctl(2) PR_CAPBSET_*/PR_CAP_AMBIENT,
# <linux/capability.h> (parsed from the guest's linux-libc-dev headers) and
# /proc/PID/status Cap* fields. The candidate is never used as an oracle.
import ctypes, errno, json, os, pathlib, re, sys

KEYS = ['permitted', 'effective', 'inheritable', 'ambient', 'bounding']
LABELS = {'permitted': 'CapPrm', 'effective': 'CapEff', 'inheritable': 'CapInh',
          'ambient': 'CapAmb', 'bounding': 'CapBnd'}
SELECTED = (1 << 13) | (1 << 39) | (1 << 40)


def names():
    text = pathlib.Path('/usr/include/linux/capability.h').read_text()
    table = {}
    for name, value in re.findall(r'^#define\s+(CAP_[A-Z_]+)\s+(\d+)\s*$', text, re.M):
        table[int(value)] = name
    last = int(pathlib.Path('/proc/sys/kernel/cap_last_cap').read_text())
    assert sorted(table) == list(range(last + 1)), ('header/kernel capability mismatch', last)
    return [table[i] for i in range(last + 1)]


NAMES = names()
FULL = (1 << len(NAMES)) - 1


class Header(ctypes.Structure):
    _fields_ = [('version', ctypes.c_uint32), ('pid', ctypes.c_int)]


class Word(ctypes.Structure):
    _fields_ = [('effective', ctypes.c_uint32), ('permitted', ctypes.c_uint32),
                ('inheritable', ctypes.c_uint32)]


def status(pid):
    lines = pathlib.Path('/proc/%d/status' % pid).read_text().splitlines()
    return dict(line.split(':', 1) for line in lines if ':' in line)


def read(pid):
    proc = status(pid)
    masks = {key: int(proc[LABELS[key]], 16) for key in KEYS}
    if os.environ.get('CAPS_ORACLE_PROC_ONLY') != '1':
        lib = ctypes.CDLL(None, use_errno=True)
        header = Header(0x20080522, pid)
        words = (Word * 2)()
        assert lib.syscall(125, ctypes.byref(header), ctypes.byref(words)) == 0, ctypes.get_errno()
        for key in KEYS[:3]:
            value = getattr(words[0], key) | (getattr(words[1], key) << 32)
            assert value == masks[key], ('capget/procfs disagree', key, value, masks[key])
    masks['euid'] = int(proc['Uid'].split()[1])
    return masks


def render(mask):
    return ','.join(NAMES[i] for i in range(len(NAMES)) if mask & (1 << i))


def describe(masks):
    return ' '.join('%s=%s' % (key, render(masks[key]) or '-') for key in KEYS)


def bits(items):
    value = 0
    for item in items:
        value |= 1 << item
    return value


def apply(prev, spec):
    expected = {}
    for key in KEYS:
        op = spec.get(key, 'keep')
        if op == 'keep':
            expected[key] = prev[key]
        elif op == 'zero':
            expected[key] = 0
        elif op == 'full':
            expected[key] = FULL
        elif op[0] == 'clear':
            expected[key] = prev[key] & ~bits(op[1])
        elif op[0] == 'set':
            expected[key] = prev[key] | bits(op[1])
        else:
            raise AssertionError(op)
    return expected


def mode_state(mode, masks, init):
    if mode == 'empty':
        return masks['euid'] == 2000 and all(masks[k] == 0 for k in KEYS[:4])
    base = masks['euid'] == 0 and masks['permitted'] == masks['effective'] == masks['bounding'] == FULL
    want = {'userns': (0, 0), 'populated': (SELECTED, SELECTED), 'inheritable': (SELECTED, 0)}[mode]
    return base and (masks['inheritable'], masks['ambient']) == want


def xattr_text(path, revision):
    raw = os.getxattr(path, 'security.capability')
    size = {2: 20, 3: 24}[revision]
    assert len(raw) == size, ('xattr size', len(raw), size)
    magic = int.from_bytes(raw[0:4], 'little')
    assert magic & 0xFF000000 == revision << 24, ('revision', hex(magic))
    words = [int.from_bytes(raw[i:i + 4], 'little') for i in range(4, 20, 4)]
    permitted = words[0] | (words[2] << 32)
    inheritable = words[1] | (words[3] << 32)
    return 'permitted=%s,inheritable=%s,effective=%d\n' % (
        render(permitted), render(inheritable), 1 if magic & 0x000001 else 0)


def check_stderr(spec, data):
    if spec == 'empty':
        return data == b''
    if spec == 'nonempty':
        return data != b''
    text = data.decode('utf-8', 'replace')
    ok = bool(data)
    for token in spec.get('contains', []):
        ok = ok and token in text
    for name in spec.get('strerror', []):
        ok = ok and os.strerror(getattr(errno, name)) in text
    for name in spec.get('lacks_strerror', []):
        ok = ok and os.strerror(getattr(errno, name)) not in text
    return ok


def check_calls(spec, lines):
    got = []
    for line in lines:
        record = json.loads(line)
        got.append([record['syscall']] + [record['arg%d' % i] for i in range(3) if 'arg%d' % i in record])
    want = []
    for item in spec:
        if item[0] == 'repeat':
            for cap in range(len(NAMES)):
                want.append([value if value != 'CAP' else cap for value in item[1]])
        else:
            want.append(item)
    return got == want, got


def observe(record):
    with open('observations.jsonl', 'a') as handle:
        handle.write(json.dumps(record, sort_keys=True) + '\n')


def calls_text():
    path = pathlib.Path('calls.jsonl')
    return path.read_text().splitlines() if path.exists() else []


def main():
    command = sys.argv[1]
    if command == 'header':
        print('capability header ok: %d names, last %s' % (len(NAMES), NAMES[-1]))
        return
    if command == 'selfcheck':
        mode = sys.argv[2]
        masks = read(os.getpid())
        if not mode_state(mode, masks, None):
            print('SETUP-INVALID selfcheck %s %s euid=%d' % (mode, describe(masks), masks['euid']))
            sys.exit(97)
        print('initial state %s ok' % mode)
        return
    spec = json.loads(pathlib.Path('spec.json').read_text())
    state = pathlib.Path('oracle-state.json')
    if command == 'start':
        key, pid, mode = sys.argv[2], int(sys.argv[3]), sys.argv[4]
        masks = read(pid)
        observe({'event': 'start', 'scope': key, 'mode': mode, 'masks': masks, 'startup_calls': calls_text()})
        if not mode_state(mode, masks, None):
            print('SETUP-INVALID %s %s euid=%d' % (key, describe(masks), masks['euid']))
            sys.exit(97)
        saved = json.loads(state.read_text()) if state.exists() else {}
        saved[key] = masks
        # Calls recorded before this point (shell start-up) are not attributed to any step.
        saved['seen:' + key] = len(calls_text())
        state.write_text(json.dumps(saved))
        return
    if command == 'step':
        scope, step, pid, code = sys.argv[2], sys.argv[3], int(sys.argv[4]), int(sys.argv[5])
        item = spec['steps'][scope + '.' + step]
        saved = json.loads(state.read_text())
        prev = saved[scope]
        out = pathlib.Path('o.' + step).read_bytes()
        err = pathlib.Path('e.' + step).read_bytes()
        problems = []
        if code != item['status']:
            problems.append('status %d, expected %d' % (code, item['status']))
        stdout = item.get('stdout', '')
        if isinstance(stdout, dict):
            stdout = xattr_text(stdout['xattr'], stdout['revision'])
        if out.decode('utf-8', 'replace') != stdout:
            problems.append('stdout %r, expected %r' % (out.decode('utf-8', 'replace'), stdout))
        if not check_stderr(item.get('stderr', 'empty'), err):
            problems.append('stderr %r does not satisfy %r' % (err.decode('utf-8', 'replace'), item.get('stderr', 'empty')))
        masks = read(pid)
        expected = apply(prev, item.get('after', {}))
        for key in KEYS:
            if masks[key] != expected[key]:
                problems.append('%s=%s, expected %s' % (key, render(masks[key]) or '-', render(expected[key]) or '-'))
        recorded = calls_text()
        step_calls = recorded[saved['seen:' + scope]:]
        if 'calls' in item:
            ok, got = check_calls(item['calls'], step_calls)
            if not ok:
                problems.append('recorded calls %s' % json.dumps(got[:6] + (['...%d total' % len(got)] if len(got) > 6 else [])))
        observe({'event': 'step', 'scope': scope, 'step': step, 'cmd': item['cmd'], 'status': code,
                 'stdout': out.decode('utf-8', 'backslashreplace'), 'stderr': err.decode('utf-8', 'backslashreplace'),
                 'before': prev, 'after': masks, 'expected_after': expected, 'step_calls': step_calls,
                 'problems': problems})
        if problems:
            print('MISMATCH %s.%s %s: %s' % (scope, step, item['cmd'], '; '.join(problems)))
            sys.exit(1)
        saved[scope] = masks
        saved['seen:' + scope] = len(recorded)
        state.write_text(json.dumps(saved))
        pathlib.Path('o.' + step).unlink()
        pathlib.Path('e.' + step).unlink()
        return
    if command == 'done':
        print('caps %s verified' % spec['name'])
        return
    raise AssertionError(command)


if __name__ == '__main__':
    main()

